using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class HouseLogisticsTests
{
    static readonly EntityId Home=new("site:castle"),Source=new("site:kofu");
    internal static WorldSession Start(string person="person:nobunaga")=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],person,1,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseLogistics.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long before=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>before);}}
    static void Move(WorldSession s,string node){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:freight-travel/"+s.Revision,node),s.Revision));Advance(s,s.Seconds+2);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==s.PlayerControl).Legs[^1].EndAt+1);}
    static EntityId Dispatch(WorldSession s,string? kind="wood",long n=10,long cash=200,EntityId? home=null,EntityId? source=null){var id=new EntityId("request:freight/"+s.Revision);Good(s.ManageHouseFreight(new(id,HouseFreightAction.Dispatch,Home:home??Home,Source:source??Source,Commodity:kind,Quantity:n,Advance:cash),s.PlayerControl,s.Revision));return id;}
    static CommandResult Act(WorldSession s,HouseFreightAction a,EntityId job,string? id=null)=>s.ManageHouseFreight(new(new(id??"request:freight-act/"+s.Revision),a,job),s.PlayerControl,s.Revision);
    [Theory][InlineData(null,10)][InlineData("wood",10)][InlineData("weapons",2)]public void ActualRoundTripTransfersHouseFundsGoodsAndUnusedCash(string? kind,long n){var s=Start();var id=Dispatch(s,kind,n);Assert.Equal(300,s.HouseTreasuryView()!.HouseCash);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Buy,id).Code);Move(s,"kofu");Good(Act(s,HouseFreightAction.Buy,id));var j=s.HouseFreightView()!.Jobs.Single();Assert.Equal(n,j.Cargo);Assert.Equal(200-j.Spent,j.Cash);Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Receive,id).Code);Move(s,"castle");Good(Act(s,HouseFreightAction.Receive,id));Assert.Equal(500-j.Spent,s.HouseTreasuryView()!.HouseCash);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(kind==null?3000+n:3000,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(kind=="wood"?20+n:20,s.HouseTreasuryView()!.Materials.Wood);Assert.Equal(kind=="weapons"?10+n:10,s.HouseTreasuryView()!.Materials.Weapons);Assert.Equal(HouseFreightPhase.Completed,s.HouseFreightView()!.Jobs.Single().Phase);}
    [Fact]public void LegacyV9HasNoFreightFieldsOrOperations(){var s=RegionalDomainTests.Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("HouseFreight",System.Text.Encoding.UTF8.GetString(b));Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));Assert.Null(s.HouseFreightView());Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Withdraw,new("request:none")).Code);}
    [Fact]public void WithdrawRetainsTrustMoneyUntilLocalReturn(){var s=Start();var id=Dispatch(s);Good(Act(s,HouseFreightAction.Withdraw,id));Assert.Equal(300,s.HouseTreasuryView()!.HouseCash);Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);Good(Act(s,HouseFreightAction.Receive,id));Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);Assert.Equal(HouseFreightPhase.Returned,s.HouseFreightView()!.Jobs.Single().Phase);}

    [Theory][InlineData(null,101,200)][InlineData("weapons",21,200)][InlineData("wood",10,201)][InlineData("wood",0,100)][InlineData("bad",1,100)][InlineData("wood",1,0)]public void InvalidScopeCannotMoveHouseMoney(string? kind,long n,long cash){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new(new("request:bad-scope"),HouseFreightAction.Dispatch,Home:Home,Source:Source,Commodity:kind,Quantity:n,Advance:cash),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void RetainerNeedsLocalHeadConsentButGetsNoGeneralTreasuryRights(){var agent=HistoricalHouseholdCatalog.Edition.People.Single().Id;var s=Start(agent.Value);Assert.Null(s.HouseTreasuryView());var id=Dispatch(s,home:Source,source:Home);Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);Assert.Null(s.HouseTreasuryView());Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),agent));Move(s,"castle");Good(Act(s,HouseFreightAction.Buy,id));Move(s,"kofu");Good(Act(s,HouseFreightAction.Receive,id));Assert.Null(s.HouseTreasuryView());Assert.Equal(30,s.DiagnosticSnapshot().Materials!.Houses.Single(h=>h.Site==Source).Wood);}
    [Fact]public void DispatchRequiresOriginalLocalHomeAndDifferentSource(){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());foreach(var home in new[]{Home,Source,new EntityId("site:kyoto")})Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new(new("request:bad-home/"+home.Value.Replace(':','/')),HouseFreightAction.Dispatch,Home:home,Source:home,Commodity:"wood",Quantity:1,Advance:100),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void RemoteStockAndPricesAreAbsentFromDispatchView(){var s=Start();var text=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.HouseFreightView()));Assert.DoesNotContain("UnitPrice",text);Assert.DoesNotContain("RiceAvailable",text);Assert.DoesNotContain("site:kofu",text);Dispatch(s);text=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.HouseFreightView()));Assert.DoesNotContain("UnitPrice",text);Assert.DoesNotContain("Markets",text);}
    [Fact]public void InsufficientActualSourcePriceLeavesTrustMoneyAndCargoIntact(){var s=Start();var id=Dispatch(s,cash:10);Move(s,"kofu");var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Buy,id).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(10,s.HouseFreightView()!.Jobs.Single().Cash);Assert.Equal(0,s.HouseFreightView()!.Jobs.Single().Cargo);Good(Act(s,HouseFreightAction.Withdraw,id));Move(s,"castle");Good(Act(s,HouseFreightAction.Receive,id));Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void TrustMoneyCannotBeSpentByPrivateTrade(){var s=Start();Dispatch(s);Good(s.ManageHouseTreasury(new(new("request:after-dispatch-fund"),TreasuryAction.Fund,Home,Amount:1000),s.PlayerControl,s.Revision));Assert.Equal(0,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);Assert.Equal(ResultCode.NotAvailable,s.TradeRice(new(new("request:private-use"),TradeAction.Quote,Home,Destination:Source,Amount:1){Commodity="wood"},s.PlayerControl,s.Revision).Code);}
    [Fact]public void PersonalAcceptedTradeAndFamilyJobShareOneCapacity(){var s=Start();Good(s.TradeRice(new(new("request:private-before-freight"),TradeAction.Quote,Home,Destination:Source,Amount:100){Commodity="wood"},s.PlayerControl,s.Revision));Good(s.TradeRice(new(new("request:private-before-accept"),TradeAction.Accept,Home,s.DiagnosticSnapshot().Trade!.Deals.Single().Id),s.PlayerControl,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new(new("request:overlap-freight"),HouseFreightAction.Dispatch,Home:Home,Source:Source,Commodity:"wood",Quantity:100,Advance:200),s.PlayerControl,s.Revision).Code);}
    [Fact]public void AdvanceEncumbersSharedBudgetAndActualCashUntilReturn(){var s=Start();var id=Dispatch(s);Assert.Equal(0,s.HouseTreasuryView()!.Remaining);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseTreasury(new(new("request:overspend-budget"),TreasuryAction.Buy,Home,"wood",1),s.PlayerControl,s.Revision).Code);Good(Act(s,HouseFreightAction.Receive,id));Assert.Equal(200,s.HouseTreasuryView()!.Remaining);Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void BudgetReductionNeverErasesInFlightTrustMoney(){var s=Start();var id=Dispatch(s);Good(s.ManageHouseTreasury(new(new("request:lower-freight-budget"),TreasuryAction.SetBudget,Home,Amount:0),s.PlayerControl,s.Revision));Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);Good(Act(s,HouseFreightAction.Receive,id));Assert.Equal(0,s.HouseTreasuryView()!.Remaining);Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void ExpiryStopsBuyingButKeepsMoneyUntilPhysicalHomeReturn(){var s=Start();var id=Dispatch(s);Move(s,"kofu");Advance(s,30*86400+1);Assert.Equal(HouseFreightPhase.ReturnRequired,s.HouseFreightView()!.Jobs.Single().Phase);Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Buy,id).Code);Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);Move(s,"castle");Good(Act(s,HouseFreightAction.Receive,id));Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void WithdrawalAfterBuyingKeepsCargoAndRefundsOnlyUnusedAdvance(){var s=Start();var id=Dispatch(s);Move(s,"kofu");Good(Act(s,HouseFreightAction.Buy,id));Good(Act(s,HouseFreightAction.Withdraw,id));var j=s.HouseFreightView()!.Jobs.Single();Assert.Equal(10,j.Cargo);Assert.Equal(140,j.Cash);Move(s,"castle");Good(Act(s,HouseFreightAction.Receive,id));Assert.Equal(440,s.HouseTreasuryView()!.HouseCash);Assert.Equal(30,s.HouseTreasuryView()!.Materials.Wood);}
    [Fact]public void TransitWithdrawalCannotBuyAndCannotReturnAcrossDistance(){var s=Start();var id=Dispatch(s);Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:freight-outbound","kofu"),s.Revision));Advance(s,2);Good(Act(s,HouseFreightAction.Withdraw,id));Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Buy,id).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Receive,id).Code);Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);}
    [Fact]public void SameReceiptAndConflictingInputsCannotDuplicateHouseGoods(){var s=Start();var id=Dispatch(s);Move(s,"kofu");Good(Act(s,HouseFreightAction.Buy,id));Move(s,"castle");Good(Act(s,HouseFreightAction.Receive,id,"request:freight-once"));Assert.Equal(ResultCode.AlreadyAccepted,Act(s,HouseFreightAction.Receive,id,"request:freight-once").Code);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,HouseFreightAction.Withdraw,id,"request:freight-once").Code);Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Receive,id).Code);Assert.Equal(30,s.HouseTreasuryView()!.Materials.Wood);}
    [Fact]public void StaleAndImpersonatedInputsCannotMoveCash(){var s=Start();long r=s.Revision;var id=Dispatch(s);var input=new HouseFreightInput(new("request:stale-freight"),HouseFreightAction.Withdraw,id);Assert.Equal(ResultCode.StateChanged,s.ManageHouseFreight(input,s.PlayerControl,r).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(input,new("person:shingen"),s.Revision).Code);Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedAdvancePriceOrReceiptCannotLoad(int phase){var s=Start();var id=Dispatch(s);Move(s,"kofu");Good(Act(s,HouseFreightAction.Buy,id));Move(s,"castle");Good(Act(s,HouseFreightAction.Receive,id));var w=s.DiagnosticSnapshot();w.HouseFreight=w.HouseFreight! with{Entries=w.HouseFreight.Entries.Select(e=>phase==0&&e.Terms!=null?e with{Terms=e.Terms with{Advance=999}}:phase==1&&e.Input.Action==HouseFreightAction.Buy?e with{UnitPrice=0}:phase==2&&e.Input.Action==HouseFreightAction.Receive?e with{At=1}:e).ToArray()};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void ActualGenerationRecoveryPreservesTrustTravelCargoWithdrawalAndReceipt(int phase){var a=Start();var id=Dispatch(a);if(phase==1){Good(a.Submit(TravelWorld.Move(a.DiagnosticSnapshot(),"request:save-freight-outbound","kofu"),a.Revision));Advance(a,2);}if(phase>=2){Move(a,"kofu");Good(Act(a,HouseFreightAction.Buy,id));if(phase==3){Good(a.Submit(TravelWorld.Move(a.DiagnosticSnapshot(),"request:save-freight-return","castle"),a.Revision));Advance(a,a.Seconds+2);}if(phase==4)Good(Act(a,HouseFreightAction.Withdraw,id));if(phase==5){Move(a,"castle");Good(Act(a,HouseFreightAction.Receive,id));}}a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"freight-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"freight",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("freight"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.HouseFreightView()),ContractJson.Write(b.HouseFreightView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"freight-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"freight-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var s in new[]{a,b}){Advance(s,s.Seconds+4*86400);if(phase!=5){if(phase<2){if(phase==0)Move(s,"kofu");Good(Act(s,HouseFreightAction.Buy,id));}if(phase!=3)Move(s,"castle");Good(Act(s,HouseFreightAction.Receive,id));}Advance(s,s.Seconds+2*86400);}Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(HouseFreightPhase.Completed,a.HouseFreightView()!.Jobs.Single().Phase);}

    [Fact]public void ActualServiceReleaseStopsNewBuyingButAllowsOldTrustReturn(){var agent=HistoricalHouseholdCatalog.Edition.People.Single().Id;var s=Start(agent.Value);var id=Dispatch(s,home:Source,source:Home);var service=NewGameService.View(s.DiagnosticSnapshot()).Cases.Single().Case;Good(s.DecideService(new(new("request:freight-service-release"),CareerAction.RequestRelease,service),s.PlayerControl,s.Revision));Advance(s,3);foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())s.Open(s.PlayerControl,m.Id,s.Revision);Assert.Null(NewGameService.View(s.DiagnosticSnapshot()).House);Move(s,"castle");Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Buy,id).Code);Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);Move(s,"kofu");Good(Act(s,HouseFreightAction.Receive,id));Assert.Equal(HouseFreightPhase.Returned,s.HouseFreightView()!.Jobs.Single().Phase);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),agent));}
    [Fact]public void NewMonthDoesNotDuplicateOrRestoreOutstandingAdvance(){var s=Start();Advance(s,29*86400);var id=Dispatch(s);Advance(s,31*86400);Assert.Equal(300,s.HouseTreasuryView()!.HouseCash);Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);Assert.False(s.HouseFreightView()!.CanDispatch);Good(Act(s,HouseFreightAction.Receive,id));Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);Assert.Equal(200,s.HouseTreasuryView()!.Remaining);}
    [Fact]public void ForeignHomeOrAlteredScopeCannotRedirectOriginalCargo(){var s=Start();var id=Dispatch(s);Move(s,"kofu");Good(Act(s,HouseFreightAction.Buy,id));var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new(new("request:redirect-freight"),HouseFreightAction.Receive,id,Home:Source),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void NormalCampaignProfileKeepsRegionalAndFreightContractsTogether(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"freight-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:nobunaga",1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,HouseLogistics.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Assert.NotNull(s.HouseFreightView());Assert.NotNull(s.HouseTreasuryView());Assert.NotNull(s.StewardshipView());Assert.Equal(30,s.DiagnosticSnapshot().Communities!.Accounts.Length);Dispatch(s);Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);}
}
